def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    boxes=[(r,c) for r in range(1,H-1) for c in range(1,W-1)
           if all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)) and g[r][c]==2]
    for (br,bc) in boxes:
        for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
            r,c=br+dr,bc+dc
            while 0<=r<H and 0<=c<W:
                if (r,c) in boxes or g[r][c]==3: break
                if g[r][c]==2:
                    # splash 3x3 around crossing, except the crossing cell itself
                    for sr in range(r-1,r+2):
                        for sc in range(c-1,c+2):
                            if 0<=sr<H and 0<=sc<W and (sr,sc)!=(r,c) and g[sr][sc]!=3 and (sr,sc) not in boxes:
                                out[sr][sc]=1
                    r+=dr; c+=dc; continue
                out[r][c]=1
                r+=dr; c+=dc
    return out

