def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    boxes=[(r,c) for r in range(1,H-1) for c in range(1,W-1)
           if g[r][c]==2 and all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0))]
    def inbox(r,c,b): return abs(r-b[0])<=1 and abs(c-b[1])<=1
    def two_or(r,c):  # orientation of 2 at (r,c): 'v','h','b' or ''
        v = (r>0 and g[r-1][c]==2) or (r<H-1 and g[r+1][c]==2)
        h = (c>0 and g[r][c-1]==2) or (c<W-1 and g[r][c+1]==2)
        return 'b' if v and h else ('v' if v else ('h' if h else ''))
    for (br,bc) in boxes:
        for dr,dc,par in ((0,1,'h'),(0,-1,'h'),(1,0,'v'),(-1,0,'v')):
            r,c=br+dr,bc+dc
            while inbox(r,c,(br,bc)) or g[r][c]==3:
                r+=dr; c+=dc
                if not (0<=r<H and 0<=c<W): break
            while 0<=r<H and 0<=c<W:
                if g[r][c]==3 or any(inbox(r,c,b) for b in boxes): break
                if g[r][c]==2:
                    o=two_or(r,c)
                    if par in ('v','h') and o in (par,'b'):
                        break  # traveling along a parallel 2-line: no beam
                    for sr in range(r-1,r+2):
                        for sc in range(c-1,c+2):
                            if 0<=sr<H and 0<=sc<W and (sr,sc)!=(r,c) and g[sr][sc]!=3 and not any(inbox(sr,sc,b) for b in boxes):
                                out[sr][sc]=1
                    r+=dr; c+=dc; continue
                out[r][c]=1
                r+=dr; c+=dc
    return out

